<template><main class="page-shell min-h-screen p-6 text-white"><section class="surface mx-auto max-w-4xl rounded-3xl p-6"><h1 class="text-3xl font-bold text-orange">เลือกที่นั่ง</h1><p class="mt-2">{{ showtime?.movie?.title }} · {{ showtime?.screen?.cinema?.name }} · {{ showtime ? new Date(showtime.startsAt).toLocaleString('th-TH') : '' }}</p><p v-if="error" class="mt-4 text-rose-300">{{ error }}</p><div class="mx-auto my-8 max-w-xl rounded bg-slate-500 p-1 text-center text-sm">จอภาพยนตร์</div><div class="mx-auto grid max-w-xl grid-cols-8 gap-2"> <button v-for="seat in seats" :key="seat.id" :disabled="seat.status!=='AVAILABLE'" @click="toggle(seat)" :class="['rounded p-2 text-xs font-bold',seat.status!=='AVAILABLE'?'bg-slate-700 text-slate-400':selected.includes(seat.id)?'bg-orange text-white':'bg-white/10 hover:bg-white/20']">{{ seat.rowLabel }}{{ seat.seatNumber }}</button></div><div class="mt-8 flex items-center justify-between"><p>เลือก {{ selected.length }} ที่ · {{ selected.length*Number(showtime?.basePrice||0) }} บาท</p><button class="primary-button" :disabled="!selected.length||busy" @click="hold">{{ busy?'กำลังจอง…':'กันที่นั่งและไปชำระเงิน' }}</button></div></section></main></template>
<script setup>
import{ref,onMounted}from"vue";import{useRoute,useRouter}from"vue-router";import axios from"axios";
const route=useRoute(),router=useRouter(),showtime=ref(null),seats=ref([]),selected=ref([]),busy=ref(false),error=ref("");
async function load(){const {data}=await axios.get(`/showtimes/${route.query.showtimeId}/seats`);showtime.value=data.showtime;seats.value=data.seats;}
function toggle(seat){selected.value=selected.value.includes(seat.id)?selected.value.filter(x=>x!==seat.id):selected.value.length<8?[...selected.value,seat.id]:selected.value;}
async function hold(){busy.value=true;error.value="";try{const {data}=await axios.post("/bookings/holds",{showtimeId:route.query.showtimeId,seatIds:selected.value},{headers:{"Idempotency-Key":crypto.randomUUID()}});router.push({path:"/payment",query:{bookingId:data.data.id}});}catch(e){error.value=e.response?.data?.error?.message||"กันที่นั่งไม่สำเร็จ กรุณาเลือกใหม่";await load();}finally{busy.value=false;}}
onMounted(async()=>{if(!route.query.showtimeId){router.replace("/");return;}try{await load();}catch(e){error.value=e.response?.data?.error?.message||"โหลดที่นั่งไม่สำเร็จ";}});
</script>
